if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    if ([string]::IsNullOrWhiteSpace($PSCommandPath)) {
        Write-Host "Please run this saved .ps1 file as Administrator." -ForegroundColor Red
        Read-Host "Press Enter to exit"
        exit 1
    }
    try {
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = (Get-Process -Id $PID).Path
        $psi.Arguments = '-NoProfile -ExecutionPolicy Bypass -STA -File "' + $PSCommandPath + '"'
        $psi.Verb = "runas"
        [System.Diagnostics.Process]::Start($psi) | Out-Null
    } catch {
        Write-Host "Administrator permission was not granted." -ForegroundColor Red
        Read-Host "Press Enter to exit"
    }
    exit
}

