        "netsh int tcp set global netdma=enabled",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters`" /v `"DisableTaskOffload`" /t REG_DWORD /d `"1`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters`" /v `"TcpAckFrequency`" /t REG_DWORD /d `"1`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters`" /v `"TcpNoDelay`" /t REG_DWORD /d `"1`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters`" /v `"TcpDelAckTicks`" /t REG_DWORD /d `"0`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters`" /v `"EnableDCA`" /t REG_DWORD /d `"1`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters`" /v `"Tcp1323Opts`" /t REG_DWORD /d `"1`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters`" /v `"TcpMaxDupAcks`" /t REG_DWORD /d `"2`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters`" /v `"DefaultTTL`" /t REG_DWORD /d `"64`" /f",
        "reg add `"HKLM\SOFTWARE\Policies\Microsoft\Windows\Psched`" /v `"NonBestEffortLimit`" /t REG_DWORD /d `"0`" /f",
        "reg add `"HKLM\SOFTWARE\Policies\Microsoft\Windows\BITS`" /v `"MaxBandwidth`" /t REG_DWORD /d `"0`" /f",
        "reg add `"HKLM\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization`" /v `"DODownloadMode`" /t REG_DWORD /d `"3`" /f",
        "reg add `"HKLM\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization`" /v `"DOMaxDownloadBandwidth`" /t REG_DWORD /d `"5`" /f",
        "reg add `"HKLM\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient`" /v `"EnableMulticast`" /t REG_DWORD /d `"0`" /f",
        "reg add `"HKLM\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient`" /v `"EnableSmartNameResolution`" /t REG_DWORD /d `"0`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\ServiceProvider`" /v `"LocalPriority`" /t REG_DWORD /d `"4`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\ServiceProvider`" /v `"HostsPriority`" /t REG_DWORD /d `"5`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\ServiceProvider`" /v `"DnsPriority`" /t REG_DWORD /d `"6`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\ServiceProvider`" /v `"NetbtPriority`" /t REG_DWORD /d `"7`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\LanmanWorkstation\Parameters`" /v `"DisableBandwidthThrottling`" /t REG_DWORD /d `"1`" /f"
    )
    for ($i=0; $i -lt $netCmds.Count; $i++) {
        Set-Progress 10 ([int](($i+1)/$netCmds.Count*100)) "internet tweaks" "Injecting internet tweaks $($i+1)/$($netCmds.Count)"
        & cmd.exe /c "$($netCmds[$i]) >nul 2>&1"
        Write-Log "  Inject -> $($netCmds[$i])" "ok"
        Start-Sleep -Milliseconds 15
    }

    $networkClass = "HKLM\SYSTEM\CurrentControlSet\Control\Class\{4D36E972-E325-11CE-BFC1-08002BE10318}"
    $ifaceKeys = Get-ChildItem -Path $networkClass -ErrorAction SilentlyContinue
    foreach ($key in $ifaceKeys) {
        $path = $key.PSPath
        $classCmds = @(
            "reg add `"$path`" /v `"*LsoV2IPv6`" /t REG_SZ /d `"1`" /f",
            "reg add `"$path`" /v `"*TCPUDPChecksumOffloadIPv4`" /t REG_SZ /d `"3`" /f",
            "reg add `"$path`" /v `"*TCPUDPChecksumOffloadIPv6`" /t REG_SZ /d `"3`" /f"
        )
        Invoke-RegCmds $classCmds
    }

    $interfaces = Get-NetAdapter | Where-Object Status -eq 'Up'
    foreach ($iface in $interfaces) {
        Set-NetAdapterAdvancedProperty -Name $iface.Name -DisplayName 'Energy Efficient Ethernet' -DisplayValue 'Disabled' -NoRestart -ErrorAction SilentlyContinue
        Set-NetAdapterAdvancedProperty -Name $iface.Name -DisplayName 'Green Ethernet' -DisplayValue 'Disabled' -NoRestart -ErrorAction SilentlyContinue
        Set-NetAdapterAdvancedProperty -Name $iface.Name -DisplayName 'Interrupt Moderation' -DisplayValue 'Disabled' -NoRestart -ErrorAction SilentlyContinue
        Set-DnsClientServerAddress -InterfaceIndex $iface.ifIndex -ServerAddresses "8.8.8.8", "8.8.4.4" -ErrorAction SilentlyContinue

        $path = "HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\$($iface.InterfaceGuid)"
        $ifaceCmds = @(
            "reg add `"$path`" /v `"TCPNoDelay`" /t REG_DWORD /d `"1`" /f",
            "reg add `"$path`" /v `"TcpAckFrequency`" /t REG_DWORD /d `"1`" /f",
            "reg add `"$path`" /v `"TcpDelAckTicks`" /t REG_DWORD /d `"0`" /f",
            "reg add `"$path`" /v `"MTU`" /t REG_DWORD /d `"3000`" /f",
            "reg add `"$path`" /v `"MSS`" /t REG_DWORD /d `"1920`" /f",
            "reg add `"$path`" /v `"TCPInitialRtt`" /t REG_DWORD /d `"300`" /f"
        )
        Invoke-RegCmds $ifaceCmds
    }
    Write-Log "[applied] internet tweaks INJECTED SUCCESSFULLY" "ok"

    Set-ModuleState 2
    Set-Progress 25 0 "registry tweaks" "Installing registry tweaks..."
    Write-Log "" "dim"
    Write-Log "[ 2 ] Injecting registry tweaks" "step"

    $powBase64 = ""
    try {
        if ($powBase64.Length -gt 50) {
            Write-Log "  SixsevenExtreme" "hi"
            $tempPowPath = "$env:TEMP\SixsevenExtreme.pow"
            [System.IO.File]::WriteAllBytes($tempPowPath, [Convert]::FromBase64String($powBase64))
            $importResult = powercfg -import $tempPowPath
            if ($importResult -match "([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})") {
                $newGuid = $matches[1]
                powercfg -changename $newGuid "SixsevenExtreme" "Best performance power plan for gaming and low latency" 
                powercfg -setactive $newGuid
    Write-Log " Custom Power Plan imported and activated successfully!" "ok"
            } else {
                Write-Log "  Failed to parse GUID from powercfg import. Trying alternative..." "warn"
            }
            
            Remove-Item -Path $tempPowPath -Force -ErrorAction SilentlyContinue
        } else {
            Write-Log "  Error: Base64 string is empty or invalid." "err"
        }
    } catch {
        Write-Log "  Error during importing custom .pow file: $_" "err"
    }

    $sysCmds = @(
        "reg add `"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile`" /v `"NetworkThrottlingIndex`" /t REG_DWORD /d `"4294967295`" /f",
        "reg add `"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile`" /v `"SystemResponsiveness`" /t REG_DWORD /d `"0`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Control\PriorityControl`" /v `"Win32PrioritySeparation`" /t REG_DWORD /d `"38`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Control\PriorityControl`" /v `"IRQ8Priority`" /t REG_DWORD /d `"1`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Control\PriorityControl`" /v `"IRQ16Priority`" /t REG_DWORD /d `"2`" /f",
        "reg add `"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games`" /v `"Scheduling Category`" /t REG_SZ /d `"High`" /f",
        "reg add `"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games`" /v `"SFIO Priority`" /t REG_SZ /d `"High`" /f",
        "reg add `"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games`" /v `"Priority`" /t REG_DWORD /d `"6`" /f",
        "reg add `"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games`" /v `"GPU Priority`" /t REG_DWORD /d `"8`" /f",
        "reg add `"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games`" /v `"Clock Rate`" /t REG_DWORD /d `"10000`" /f",
        "reg add `"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Low Latency`" /v `"Priority`" /t REG_DWORD /d `"1`" /f",
        "reg add `"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Low Latency`" /v `"Latency Sensitive`" /t REG_SZ /d `"True`" /f",
        "reg add `"HKLM\SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection`" /v `"DisableRealtimeMonitoring`" /t REG_DWORD /d `"1`" /f",
        "reg add `"HKLM\SOFTWARE\Policies\Microsoft\WindowsFirewall\DomainProfile`" /v `"EnableFirewall`" /t REG_DWORD /d `"0`" /f",
        "reg add `"HKLM\SOFTWARE\Policies\Microsoft\WindowsFirewall\StandardProfile`" /v `"EnableFirewall`" /t REG_DWORD /d `"0`" /f"
    )
    for ($i=0; $i -lt $sysCmds.Count; $i++) {
        Set-Progress 40 ([int](($i+1)/$sysCmds.Count*100)) "registry tweaks" "Injecting registry tweaks $($i+1)/$($sysCmds.Count)"
        & cmd.exe /c "$($sysCmds[$i]) >nul 2>&1"
        Write-Log "  Inject -> $($sysCmds[$i])" "ok"
        Start-Sleep -Milliseconds 15
    }

    & cmd.exe /c "powercfg -setacvalueindex SCHEME_CURRENT SUB_PCIEXPRESS ASPM 0" | Out-Null
    & cmd.exe /c "powercfg -setactive SCHEME_CURRENT" | Out-Null

    $bcdCmds = @(
        "bcdedit /set useplatformtick yes",
        "bcdedit /set disabledynamictick yes",
        "bcdedit /set tscsyncpolicy Enhanced",
        "bcdedit /deletevalue useplatformclock",
        "bcdedit /set nx optout",
        "bcdedit /set hypervisorlaunchtype off",
        "bcdedit /set tpmbootentropy ForceDisable"
    )
    foreach ($cmd in $bcdCmds) { & cmd.exe /c "$cmd 2>nul" | Out-Null }
    Write-Log "[applied] registry tweaks INJECTED SUCCESSFULLY" "ok"

    Set-ModuleState 3
    Set-Progress 60 0 "latency tweaks" "Installing latency tweaks..."
    Write-Log "" "dim"
    Write-Log "[ 3 ] Injecting latency tweaks"  "step"

    $inpCmds = @(
        "reg add `"HKCU\Control Panel\Keyboard`" /v `"KeyboardDelay`" /t REG_SZ /d `"0`" /f",
        "reg add `"HKCU\Control Panel\Keyboard`" /v `"KeyboardSpeed`" /t REG_SZ /d `"31`" /f",
        "reg add `"HKCU\Control Panel\Accessibility\Keyboard Response`" /v `"AutoRepeatDelay`" /t REG_SZ /d `"150`" /f",
        "reg add `"HKCU\Control Panel\Accessibility\Keyboard Response`" /v `"AutoRepeatRate`" /t REG_SZ /d `"1`" /f",
        "reg add `"HKCU\Control Panel\Accessibility\Keyboard Response`" /v `"BounceTime`" /t REG_SZ /d `"0`" /f",
        "reg add `"HKCU\Control Panel\Accessibility\Keyboard Response`" /v `"DelayBeforeAcceptance`" /t REG_SZ /d `"0`" /f",
        "reg add `"HKCU\Control Panel\Accessibility\Keyboard Response`" /v `"Flags`" /t REG_SZ /d `"59`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\mouclass\Parameters`" /v `"MouseDataQueueSize`" /t REG_DWORD /d `"32`" /f",
        "reg add `"HKLM\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters`" /v `"KeyboardDataQueueSize`" /t REG_DWORD /d `"32`" /f",
        "reg add `"HKCU\Control Panel\Mouse`" /v `"MouseSpeed`" /t REG_SZ /d `"0`" /f",
        "reg add `"HKU\.DEFAULT\Control Panel\Mouse`" /v `"MouseThreshold1`" /t REG_SZ /d `"0`" /f",
        "reg add `"HKU\.DEFAULT\Control Panel\Mouse`" /v `"MouseThreshold2`" /t REG_SZ /d `"0`" /f"
    )
    for ($i=0; $i -lt $inpCmds.Count; $i++) {
        Set-Progress 75 ([int](($i+1)/$inpCmds.Count*100)) "latency tweaks" "Injecting latency tweaks $($i+1)/$($inpCmds.Count)"
        & cmd.exe /c "$($inpCmds[$i]) >nul 2>&1"
        Write-Log "  Inject -> $($inpCmds[$i])" "ok"
        Start-Sleep -Milliseconds 15
    }

    $xCurveHex = "0000000000000000C0CC0C0000000000809919000000000040662600000000000033330000000000"
    $yCurveHex = "0000000000000000000038000000000000007000000000000000A800000000000000E00000000000"
    & cmd.exe /c "reg add `"HKCU\Control Panel\Mouse`" /v `"SmoothMouseXCurve`" /t REG_BINARY /d `"$xCurveHex`" /f" | Out-Null
    & cmd.exe /c "reg add `"HKCU\Control Panel\Mouse`" /v `"SmoothMouseYCurve`" /t REG_BINARY /d `"$yCurveHex`" /f" | Out-Null
    Write-Log "[applied] latency tweaks INJECTED SUCCESSFULLY" "ok"

    Set-ModuleState 4
    Set-Progress 85 0 "overall tweaks" "Installing overall tweaks..."
    Write-Log "" "dim"
    Write-Log "[ 4 ] Injecting overall tweaks" "step"

    Remove-Item -Path "$env:TEMP\*" -Recurse -Force -ErrorAction SilentlyContinue
    Set-Progress 90 40 "SYSTEM PURGE" "Wiping User Temp directories..."
    Remove-Item -Path "C:\Windows\Temp\*" -Recurse -Force -ErrorAction SilentlyContinue
    Set-Progress 95 70 "SYSTEM PURGE" "Wiping Core System Temp..."
    Remove-Item -Path "C:\Windows\Prefetch\*" -Recurse -Force -ErrorAction SilentlyContinue
    Set-Progress 100 90 "SYSTEM PURGE" "Flushing OS Prefetch memory..."
    & cmd.exe /c "ipconfig /flushdns" | Out-Null
    Write-Log "[applied] overall tweaks INJECTED SUCCESSFULLY" "ok"

    foreach ($m in $moduleMeta) {
        $moduleTitleLabels[$m.id].ForeColor = $NEON_B
        $moduleIcons[$m.id].ForeColor = $NEON_B
        $moduleIcons[$m.id].Text = "[ OK ]"
    }

    Set-Progress 100 100 "All tweaks applied successfully!" "System is ready. Reboot recommended for setting noctivane."
    $status.Text = "STATUS: SUCCESS"
    $status.ForeColor = $NEON_B
    $heroLeft.Text = "COMPLETED"

    Write-Log "" "dim"
    Write-Log "==============================================" "dim"
    Write-Log "          inject noctivane successfully" "ok"
    Write-Log "==============================================" "dim"

    $btnRun.Enabled = $true
    $btnRun.ForeColor = $NEON_A
    $btnRun.Text = "INJECT NOCTIVANE"

    Start-Sleep -Milliseconds 300
    [System.Windows.Forms.MessageBox]::Show("NOCTIVANE : INJECT SUCCESSFUL`n`nAll noctivane tweaks successfully applied.`nRestart your Pc to use noctivane.", "NOCTIVANE", 0, 64)
})

$btnReset.Add_Click({
    $logBox.Clear()
    $mainBar.Value = 0
    $subBar.Value = 0
    $percent.Text = "0%"
    $currentTask.Text = "Waiting to inject..."
    $currentSub.Text = "Click Inject below to start the noctivane"
    $status.Text = "STATUS: SUCCESS"
    $status.ForeColor = $NEON_B
    $heroLeft.Text = "READY TO INJECT"
    $btnRun.Text = "INJECT NOCTIVANE"

    foreach ($m in $moduleMeta) {
        $moduleTitleLabels[$m.id].ForeColor = $WHITEISH
        $moduleIcons[$m.id].ForeColor = $TEXTDIM
        $moduleIcons[$m.id].Text = "[ 0$($m.id) ]"
    }
    Write-Log "Logs cleared." "hi"
})

$btnExit.Add_Click({ $form.Close() })
$btnClose.Add_Click({ $form.Close() })
$btnMin.Add_Click({ $form.WindowState = "Minimized" })

$form.Add_FormClosing({
    try { $usageTimer.Stop() } catch {}
    try { if ($script:cpuCounter) { $script:cpuCounter.Dispose() } } catch {}
    try { if ($script:memCounter) { $script:memCounter.Dispose() } } catch {}
    try { Clear-History; Remove-Item -Path ((Get-PSReadLineOption -ErrorAction SilentlyContinue).HistorySavePath) -Force -ErrorAction SilentlyContinue } catch {}
})

$usageTimer = New-Object System.Windows.Forms.Timer
$usageTimer.Interval = 1500
$usageTimer.Add_Tick({ Update-LiveLoad })

$form.Add_Shown({
    Update-LiveLoad
    $usageTimer.Start()
})

Write-Log "noctivane interface initialized" "hi"
Write-Log "OS: $osInfo" "dim"
Write-Log "CPU: $cpuInfo" "dim"
Write-Log "RAM: $ramGB GB Detected" "dim"
Write-Log "" "dim"
Write-Log "Available Steps :" "step"
Write-Log "  > internet tweaks" "ok"
Write-Log "  > registry tweaks" "ok"
Write-Log "  > latency tweaks" "ok"
Write-Log "  > overall tweaks" "ok"
Write-Log "" "dim"
Write-Log "Click [ INJECT NOCTIVANE ] to apply noctivane." "ok"

try {
    [System.Windows.Forms.Application]::Run($form)
} catch {
    Write-Host "NOCTIVANE INJECT ERROR: $_" -ForegroundColor Red
    Read-Host "Press Enter to force exit"
}
